"""Guardrail eval: recall on advice phrasing and false positives on clean text.

Two labeled sets, English and Brazilian Portuguese:

* ``guardrail_dev.jsonl``: written by hand before the v0.6 patterns, then used to
  design them. Scores on it are in-sample for v0.6 (optimistic).
* ``guardrail_heldout.jsonl``: generated by a different author (a local LLM,
  see ``data/README.md``) after the v0.6 patterns were frozen. The out-of-sample
  number.

The v0.5 substring deny-list is kept here verbatim as the baseline.
"""

from __future__ import annotations

import json
from collections.abc import Callable
from dataclasses import dataclass
from importlib import resources

from quantlens import guardrails
from quantlens.evals.stats import Rate, wilson

V05_DISALLOWED = (
    "should buy",
    "should sell",
    "buy now",
    "sell now",
    "recommend buying",
    "recommend selling",
    "you should",
    "guaranteed",
    "can't lose",
    "cannot lose",
    "risk-free",
    "sure thing",
)

Blocker = Callable[[str], bool]


@dataclass(frozen=True)
class Example:
    text: str
    label: str
    lang: str


@dataclass(frozen=True)
class GuardrailScore:
    system: str
    dataset: str
    recall: Rate
    false_positive: Rate
    missed: tuple[str, ...]
    wrongly_blocked: tuple[str, ...]


def v05_blocks(text: str) -> bool:
    lowered = text.lower()
    return any(phrase in lowered for phrase in V05_DISALLOWED)


def current_blocks(text: str) -> bool:
    return not guardrails.validate(text).ok


SYSTEMS: dict[str, Blocker] = {"v0.5 deny-list": v05_blocks, "v0.6 patterns": current_blocks}


def load(name: str) -> tuple[Example, ...]:
    path = resources.files("quantlens.evals").joinpath(f"data/{name}.jsonl")
    lines = path.read_text(encoding="utf-8").splitlines()
    return tuple(Example(**json.loads(line)) for line in lines if line.strip())


def score(
    system: str, blocks: Blocker, dataset: str, examples: tuple[Example, ...]
) -> GuardrailScore:
    advice = [e for e in examples if e.label == "advice"]
    clean = [e for e in examples if e.label == "clean"]
    missed = tuple(e.text for e in advice if not blocks(e.text))
    wrong = tuple(e.text for e in clean if blocks(e.text))
    return GuardrailScore(
        system=system,
        dataset=dataset,
        recall=wilson(len(advice) - len(missed), len(advice)),
        false_positive=wilson(len(wrong), len(clean)),
        missed=missed,
        wrongly_blocked=wrong,
    )


DATASETS = ("guardrail_dev",)


def run(datasets: tuple[str, ...] = DATASETS) -> list[GuardrailScore]:
    scores = []
    for dataset in datasets:
        examples = load(dataset)
        for lang in ("en", "pt", "all"):
            subset = tuple(e for e in examples if lang in ("all", e.lang))
            for name, blocks in SYSTEMS.items():
                scores.append(score(name, blocks, f"{dataset}/{lang}", subset))
    return scores


def report(scores: list[GuardrailScore]) -> list[str]:
    lines = ["Guardrail: recall on advice, false positives on clean text (95% Wilson)"]
    lines.append(f"  {'dataset':22} {'system':16} {'recall':>28} {'false positive':>26}")
    for s in scores:
        lines.append(f"  {s.dataset:22} {s.system:16} {s.recall!s:>28} {s.false_positive!s:>26}")
    return lines


def measured(scores: list[GuardrailScore]) -> dict[str, float]:
    """Gate inputs: v0.6 recall and false-positive rate on every dataset (all languages)."""
    out: dict[str, float] = {}
    for s in scores:
        if s.system != "v0.6 patterns" or not s.dataset.endswith("/all"):
            continue
        dataset = s.dataset.removesuffix("/all")
        out[f"guardrail.{dataset}.recall"] = s.recall.value
        out[f"guardrail.{dataset}.false_positive"] = s.false_positive.value
    return out
